// Minimal session store for TempData
file class SessionStore : ISessionStore
{
    private readonly Dictionary<string, byte[]> _store = new();

    public bool TryGetValue(string key, out byte[] value) => _store.TryGetValue(key, out value!);
    public void Set(string key, byte[] value) => _store[key] = value;
}

file interface ISessionStore { }

// Minimal TempData provider that doesn't require session
file class SessionStateTempDataProvider : ITempDataProvider
{
    public SessionStateTempDataProvider(SessionStore store) { }

    public IDictionary<string, object?> LoadTempData(HttpContext context) => new Dictionary<string, object?>();
    public void SaveTempData(HttpContext context, IDictionary<string, object?> values) { }
}

