using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.CreateSeeded();
        _controller = new StudentsController(_context);
        // Set up TempData for controller
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), new SessionStateTempDataProvider(new SessionStore()));
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    #region Index

    [Fact]
    public void Index_NoParameters_ReturnsViewWithStudents()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.True(model.Count > 0);
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        var names = model.Select(s => s.LastName).ToList();
        Assert.Equal(names.OrderBy(n => n), names);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        var names = model.Select(s => s.LastName).ToList();
        Assert.Equal(names.OrderByDescending(n => n), names);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        var dates = model.Select(s => s.EnrollmentDate).ToList();
        Assert.Equal(dates.OrderBy(d => d), dates);
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        var dates = model.Select(s => s.EnrollmentDate).ToList();
        Assert.Equal(dates.OrderByDescending(d => d), dates);
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByLastName()
    {
        var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByFirstName()
    {
        var result = _controller.Index(null, null, "Meredith", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Meredith", model[0].FirstMidName);
    }

    [Fact]
    public void Index_NewSearchString_ResetsPage()
    {
        var result = _controller.Index(null, null, "Alex", null) as ViewResult;

        // When searchString is provided, page resets to 1
        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        var result = _controller.Index(null, "Alexander", null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Index_SetsViewBagSortParameters()
    {
        _controller.Index(null, null, null, null);

        Assert.Null(_controller.ViewBag.CurrentSort);
        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_WithSortOrder_SetsCorrectToggleValues()
    {
        _controller.Index("Date", null, null, null);

        Assert.Equal("Date", _controller.ViewBag.CurrentSort);
        Assert.Equal("", _controller.ViewBag.NameSortParm);
        Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
    }

    #endregion

    #region Details

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var student = _context.Students.First();

        var result = _controller.Details(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Details_ValidId_IncludesEnrollments()
    {
        var student = _context.Students.First();

        var result = _controller.Details(student.ID) as ViewResult;

        var model = Assert.IsType<Student>(result!.Model);
        Assert.NotNull(model.Enrollments);
    }

    #endregion

    #region Create GET

    [Fact]
    public void Create_Get_ReturnsViewWithNewStudent()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    #endregion

    #region Create POST

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2023-01-15")
        };

        var result = _controller.Create(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidStudent_SavesInDatabase()
    {
        var student = new Student
        {
            FirstMidName = "New",
            LastName = "Person",
            EnrollmentDate = DateTime.Parse("2023-06-01")
        };

        _controller.Create(student);

        Assert.True(_context.Students.Any(s => s.LastName == "Person"));
    }

    [Fact]
    public void Create_Post_MinValueDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Invalid",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_DateTooEarly_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Invalid",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            FirstMidName = "Test",
            EnrollmentDate = DateTime.Parse("2023-01-15")
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.Same(student, result.Model);
    }

    #endregion

    #region Edit GET

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        var student = _context.Students.First();

        var result = _controller.Edit(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Edit_Get_NonExistentId_ReturnsNotFound()
    {
        var result = _controller.Edit(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    #endregion

    #region Edit POST

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        var student = _context.Students.First();
        // Detach to simulate form submission
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        student.FirstMidName = "Updated";

        var result = _controller.Edit(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_MinValueDate_AddsModelError()
    {
        var student = _context.Students.First();
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        student.EnrollmentDate = DateTime.MinValue;

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = _context.Students.First();

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
    }

    #endregion

    #region Delete GET

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        var student = _context.Students.First();

        var result = _controller.Delete(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Delete_Get_NonExistentId_ReturnsNotFound()
    {
        var result = _controller.Delete(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    #endregion

    #region Delete POST

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        var student = _context.Students.First();
        var studentId = student.ID;

        var result = _controller.DeleteConfirmed(studentId);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Students.Find(studentId));
    }

    #endregion
}

// Minimal session store for TempData
file class SessionStore : ISessionStore
{
    private readonly Dictionary<string, byte[]> _store = new();

    public bool TryGetValue(string key, out byte[] value) => _store.TryGetValue(key, out value!);
    public void Set(string key, byte[] value) => _store[key] = value;
}

file interface ISessionStore { }

// Minimal TempData provider that doesn't require session
file class SessionStateTempDataProvider : ITempDataProvider
{
    public SessionStateTempDataProvider(SessionStore store) { }

    public IDictionary<string, object?> LoadTempData(HttpContext context) => new Dictionary<string, object?>();
    public void SaveTempData(HttpContext context, IDictionary<string, object?> values) { }
}

