using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.CreateSeeded();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    #region Index

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<IEnumerable<Course>>(result.Model);
        Assert.Equal(2, model.Count());
    }

    [Fact]
    public void Index_IncludesDepartment()
    {
        var result = _controller.Index() as ViewResult;

        var model = Assert.IsAssignableFrom<IEnumerable<Course>>(result!.Model);
        Assert.All(model, c => Assert.NotNull(c.Department));
    }

    #endregion

    #region Details

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        var course = _context.Courses.First();

        var result = _controller.Details(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
        Assert.NotNull(model.Department);
    }

    #endregion

    #region Create GET

    [Fact]
    public void Create_Get_ReturnsViewWithDepartmentSelectList()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    #endregion

    #region Create POST

    [Fact]
    public void Create_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        var dept = _context.Departments.First();
        var course = new Course
        {
            CourseID = 9999,
            Title = "New Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        var result = _controller.Create(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidCourse_SavesInDatabase()
    {
        var dept = _context.Departments.First();
        var course = new Course
        {
            CourseID = 8888,
            Title = "Saved Course",
            Credits = 4,
            DepartmentID = dept.DepartmentID
        };

        _controller.Create(course, null!);

        Assert.True(_context.Courses.Any(c => c.CourseID == 8888));
    }

    [Fact]
    public void Create_Post_InvalidExtension_ReturnsViewWithError()
    {
        var dept = _context.Departments.First();
        var course = new Course { CourseID = 7777, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.exe");
        fileMock.Setup(f => f.Length).Returns(100);

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsViewWithError()
    {
        var dept = _context.Departments.First();
        var course = new Course { CourseID = 6666, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.jpg");
        fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errorMessages = _controller.ModelState["teachingMaterialImage"]!.Errors;
        Assert.Contains(errorMessages, e => e.ErrorMessage.Contains("5MB"));
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 5555, Title = "", Credits = 3 };

        var result = _controller.Create(course, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Create_Post_ValidFile_SavesFileAndSetsPath()
    {
        var dept = _context.Departments.First();
        var course = new Course { CourseID = 4444, Title = "WithImage", Credits = 3, DepartmentID = dept.DepartmentID };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("material.png");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, fileMock.Object);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        var saved = _context.Courses.Find(4444);
        Assert.NotNull(saved);
        Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
    }

    #endregion

    #region Edit GET

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithCourse()
    {
        var course = _context.Courses.First();

        var result = _controller.Edit(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Edit_Get_NonExistentId_ReturnsNotFound()
    {
        var result = _controller.Edit(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    #endregion

    #region Edit POST

    [Fact]
    public void Edit_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        var course = _context.Courses.First();
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = _controller.Edit(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidExtension_ReturnsError()
    {
        var course = _context.Courses.First();
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.txt");
        fileMock.Setup(f => f.Length).Returns(100);

        var result = _controller.Edit(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = _context.Courses.First();

        var result = _controller.Edit(course, null!) as ViewResult;

        Assert.NotNull(result);
    }

    #endregion

    #region Delete GET

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithCourse()
    {
        var course = _context.Courses.First();

        var result = _controller.Delete(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
    }

    #endregion

    #region Delete POST

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
    {
        var course = _context.Courses.First();
        var courseId = course.CourseID;

        var result = _controller.DeleteConfirmed(courseId);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Courses.Find(courseId));
    }

    #endregion
}

