using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Net;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.CreateSeeded();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    #region Index

    [Fact]
    public void Index_NoParameters_ReturnsViewWithInstructors()
    {
        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Instructors);
        Assert.True(model.Instructors.Count() > 0);
    }

    [Fact]
    public void Index_InstructorsOrderedByLastName()
    {
        var result = _controller.Index(null, null) as ViewResult;

        var model = Assert.IsType<InstructorIndexData>(result!.Model);
        var names = model.Instructors.Select(i => i.LastName).ToList();
        Assert.Equal(names.OrderBy(n => n), names);
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var instructor = _context.Instructors
            .Include(i => i.CourseAssignments)
            .First(i => i.CourseAssignments.Any());

        var result = _controller.Index(instructor.ID, null) as ViewResult;

        var model = Assert.IsType<InstructorIndexData>(result!.Model);
        Assert.NotNull(model.Courses);
        Assert.True(model.Courses.Any());
    }

    [Fact]
    public void Index_WithInstructorId_SetsViewBagInstructorID()
    {
        var instructor = _context.Instructors.First();

        _controller.Index(instructor.ID, null);

        Assert.Equal(instructor.ID, _controller.ViewBag.InstructorID);
    }

    [Fact]
    public void Index_WithCourseId_PopulatesEnrollments()
    {
        var instructor = _context.Instructors
            .Include(i => i.CourseAssignments)
            .First(i => i.CourseAssignments.Any());
        var courseId = instructor.CourseAssignments.First().CourseID;

        var result = _controller.Index(instructor.ID, courseId) as ViewResult;

        var model = Assert.IsType<InstructorIndexData>(result!.Model);
        Assert.NotNull(model.Enrollments);
    }

    #endregion

    #region Details

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = _context.Instructors.First();

        var result = _controller.Details(instructor.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    [Fact]
    public void Details_NonExistentId_ReturnsNotFound()
    {
        var result = _controller.Details(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    #endregion

    #region Create GET

    [Fact]
    public void Create_Get_ReturnsViewWithInstructor()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    [Fact]
    public void Create_Get_PopulatesAssignedCourseData()
    {
        var result = _controller.Create() as ViewResult;

        var courses = _controller.ViewBag.Courses as List<AssignedCourseData>;
        Assert.NotNull(courses);
        Assert.True(courses.Count > 0);
        Assert.All(courses, c => Assert.False(c.Assigned));
    }

    #endregion

    #region Create POST

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Instructor",
            HireDate = DateTime.Parse("2020-01-01")
        };

        var result = _controller.Create(instructor, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AssignsCourses()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Course",
            LastName = "Teacher",
            HireDate = DateTime.Parse("2020-01-01")
        };
        var courseIds = _context.Courses.Select(c => c.CourseID.ToString()).ToArray();

        var result = _controller.Create(instructor, courseIds);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .First(i => i.LastName == "Teacher");
        Assert.Equal(courseIds.Length, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            HireDate = DateTime.Parse("2020-01-01")
        };

        var result = _controller.Create(instructor, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    #endregion

    #region Edit GET

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = _context.Instructors.First();

        var result = _controller.Edit(instructor.ID) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    #endregion

    #region Delete GET

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = _context.Instructors.First();

        var result = _controller.Delete(instructor.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    [Fact]
    public void Delete_Get_NonExistentId_ReturnsNotFound()
    {
        var result = _controller.Delete(99999);

        Assert.IsType<NotFoundResult>(result);
    }

    #endregion

    #region Delete POST

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
    {
        // Use instructor without department reference to avoid null ref
        var instructor = _context.Instructors
            .Include(i => i.OfficeAssignment)
            .First(i => !_context.Departments.Any(d => d.InstructorID == i.ID));

        var result = _controller.DeleteConfirmed(instructor.ID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Instructors.Find(instructor.ID));
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsDepartmentAdmin_NullsOutDepartmentReference()
    {
        var dept = _context.Departments.First(d => d.InstructorID != null);
        var instructorId = dept.InstructorID!.Value;

        _controller.DeleteConfirmed(instructorId);

        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.NotNull(updatedDept);
        Assert.Null(updatedDept.InstructorID);
    }

    #endregion
}

