using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void CanCreateContext_WithInMemoryProvider()
    {
        using var context = TestDbContextFactory.Create();

        Assert.NotNull(context);
        Assert.NotNull(context.Students);
        Assert.NotNull(context.Courses);
        Assert.NotNull(context.Departments);
        Assert.NotNull(context.Instructors);
        Assert.NotNull(context.Enrollments);
    }

    [Fact]
    public void CanAddAndRetrieveStudent()
    {
        using var context = TestDbContextFactory.Create();

        context.Students.Add(new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = DateTime.Parse("2023-01-01")
        });
        context.SaveChanges();

        var student = context.Students.FirstOrDefault(s => s.LastName == "User");
        Assert.NotNull(student);
        Assert.Equal("Test", student.FirstMidName);
    }

    [Fact]
    public void CourseAssignment_HasCompositeKey()
    {
        using var context = TestDbContextFactory.CreateSeeded();

        var assignment = context.CourseAssignments.First();
        Assert.True(assignment.CourseID > 0);
        Assert.True(assignment.InstructorID > 0);
    }

    [Fact]
    public void CourseAssignment_NavigationProperties_Work()
    {
        using var context = TestDbContextFactory.CreateSeeded();

        var assignment = context.CourseAssignments
            .Include(ca => ca.Course)
            .Include(ca => ca.Instructor)
            .First();

        Assert.NotNull(assignment.Course);
        Assert.NotNull(assignment.Instructor);
    }

    [Fact]
    public void OfficeAssignment_OneToOne_WithInstructor()
    {
        using var context = TestDbContextFactory.CreateSeeded();

        var office = context.OfficeAssignments
            .Include(o => o.Instructor)
            .First();

        Assert.NotNull(office.Instructor);
        Assert.Equal(office.InstructorID, office.Instructor.ID);
    }

    [Fact]
    public void Department_HasOptionalAdministrator()
    {
        using var context = TestDbContextFactory.CreateSeeded();

        var dept = context.Departments
            .Include(d => d.Administrator)
            .First();

        Assert.NotNull(dept.Administrator);
        Assert.Equal(dept.InstructorID, dept.Administrator.ID);
    }

    [Fact]
    public void Enrollment_HasCourseAndStudentRelationship()
    {
        using var context = TestDbContextFactory.CreateSeeded();

        var enrollment = context.Enrollments
            .Include(e => e.Course)
