    {
        DrainQueue();

        _sut.SendNotification("Dept", "1", "Science", operation);

        // Drain until we find ours (other parallel tests may have enqueued)
        Notification? found = null;
        Notification? candidate;
        while ((candidate = _sut.ReceiveNotification()) != null)
        {
            if (candidate.EntityType == "Dept" && candidate.EntityId == "1")
            {
                found = candidate;
                break;
            }
        }

        Assert.NotNull(found);
        Assert.Contains(expectedVerb, found.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        DrainQueue();

        var result = _sut.ReceiveNotification();

        Assert.Null(result);
