 using ContosoUniversity.Models;
 using ContosoUniversity.Services;

 namespace ContosoUniversity.Tests.Services;

 [Collection("NotificationServiceTests")]
 public class NotificationServiceTests : IDisposable
 {
     private readonly NotificationService _sut = new();

     public void Dispose() => _sut.Dispose();

     /// <summary>
     /// Drains the static shared queue so tests get deterministic results.
     /// Must be called before any test that reads from the queue.
     /// </summary>
     private static void DrainQueue()
     {
         using var drainer = new NotificationService();
         while (drainer.ReceiveNotification() != null) { }
     }

     [Fact]
     public void SendNotification_WithDisplayName_EnqueuesNotificationWithCorrectMessage()
     {
         var uniqueId = Guid.NewGuid().ToString();
         _sut.SendNotification("Student", uniqueId, "John Doe", EntityOperation.CREATE, "Admin");

         var notification = FindNotification(uniqueId);

         Assert.NotNull(notification);
         Assert.Equal("Student", notification.EntityType);
         Assert.Equal(uniqueId, notification.EntityId);
         Assert.Equal("CREATE", notification.Operation);
         Assert.Contains("John Doe", notification.Message);
         Assert.Contains("created", notification.Message);
         Assert.Equal("Admin", notification.CreatedBy);
         Assert.False(notification.IsRead);
     }

     [Fact]
     public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
     {
         var uniqueId = Guid.NewGuid().ToString();
         _sut.SendNotification("Course", uniqueId, EntityOperation.UPDATE);

         var notification = FindNotification(uniqueId);

         Assert.NotNull(notification);
         Assert.Contains($"ID: {uniqueId}", notification.Message);
         Assert.Contains("updated", notification.Message);
         Assert.Equal("System", notification.CreatedBy);
     }

     [Theory]
     [InlineData(EntityOperation.CREATE, "created")]
     [InlineData(EntityOperation.UPDATE, "updated")]
     [InlineData(EntityOperation.DELETE, "deleted")]
     public void SendNotification_OperationTypes_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
     {
         var uniqueId = Guid.NewGuid().ToString();
         _sut.SendNotification("Dept", uniqueId, "Science", operation);

         var found = FindNotification(uniqueId);

         Assert.NotNull(found);
         Assert.Contains(expectedVerb, found.Message);
     }

     [Fact]
     public void ReceiveNotification_AfterDrain_ReturnsNullOrNotification()
     {
         // The queue is static/shared, so we can only verify the method doesn't throw
         var ex = Record.Exception(() => _sut.ReceiveNotification());
         Assert.Null(ex);
     }

     [Fact]
     public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
     {
         DrainQueue();

         var id1 = Guid.NewGuid().ToString();
         var id2 = Guid.NewGuid().ToString();
         _sut.SendNotification("A", id1, "First", EntityOperation.CREATE);
         _sut.SendNotification("B", id2, "Second", EntityOperation.UPDATE);

         var first = FindNotification(id1);
         var second = FindNotification(id2);

         Assert.NotNull(first);
         Assert.NotNull(second);
         Assert.Equal("A", first.EntityType);
         Assert.Equal("B", second.EntityType);
     }

     [Fact]
     public void MarkAsRead_DoesNotThrow()
     {
         var ex = Record.Exception(() => _sut.MarkAsRead(999));
         Assert.Null(ex);
     }

     [Fact]
     public void SendNotification_SetsCreatedAtToApproximatelyNow()
     {
         var uniqueId = Guid.NewGuid().ToString();
         var before = DateTime.Now;
         _sut.SendNotification("Test", uniqueId, "TestItem", EntityOperation.CREATE);
         var after = DateTime.Now;

         var notification = FindNotification(uniqueId);

         Assert.NotNull(notification);
         Assert.InRange(notification.CreatedAt, before, after);
     }

     [Fact]
     public void Dispose_CanBeCalledMultipleTimes()
     {
         var service = new NotificationService();
         service.Dispose();
         var ex = Record.Exception(() => service.Dispose());
         Assert.Null(ex);
     }
 }

