{
    using var drainer = new NotificationService();
    while (drainer.ReceiveNotification() != null) { }
}

/// <summary>
/// Drains the queue looking for a notification with the given entityId.
/// Uses unique GUIDs to avoid interference from parallel tests.
/// </summary>
private Notification? FindNotification(string entityId)
{
    Notification? candidate;
    while ((candidate = _sut.ReceiveNotification()) != null)
    {
        if (candidate.EntityId == entityId)
            return candidate;
    }
    return null;
}

